'use strict';const form=document.querySelector('#bootstrap-form'),status=document.querySelector('#bootstrap-status');form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);status.textContent='Hesap oluşturuluyor…';try{const response=await fetch('/api/admin-bootstrap',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({bootstrap_secret:f.get('bootstrap_secret'),email:f.get('email'),password:f.get('password')})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Kurulum tamamlanamadı.');form.reset();status.textContent='Yönetici hesabı oluşturuldu. Cloudflare’dan kurulum secret’ını kaldırıp giriş sayfasına geç.';}catch(err){status.textContent=err.message;status.classList.add('bad')}});
